+    padding: 0.2rem;
+    border-radius: 4px;
+}
+
+.emoji-option:hover {
+    background: #f1f3f5;
+}
+
+/* Message input */
+.message-input {
+    display: flex;
+    gap: 0.5rem;
+    padding: 0.8rem 1rem;
+    border-top: 1px solid #dee2e6;
+    background: white;
+}
+
+.message-input textarea {
+    flex: 1;
+    resize: none;
+    border: 1px solid #dee2e6;
+    border-radius: 6px;
+    padding: 0.5rem 0.8rem;
+    font-size: 0.9rem;
+    font-family: inherit;
+    outline: none;
+    transition: border-color 0.15s;
+}
+
+.message-input textarea:focus {
+    border-color: #2563eb;
+}
+
+.send-btn {
+    background: #2563eb;
+    color: white;
+    border: none;
+    border-radius: 6px;
+    padding: 0.5rem 1rem;
