+}
+
+.send-btn:hover:not(:disabled) {
+    background: #1d4ed8;
+}
+
+.send-btn:disabled {
+    background: #93c5fd;
+    cursor: not-allowed;
+}
+
+/* Thread panel */
+.chat-thread-panel {
