+    border-bottom: 1px solid #dee2e6;
+}
+
+.thread-header h4 {
+    margin: 0;
+    font-size: 1rem;
+}
+
+.close-btn {
+    background: none;
+    border: none;
+    font-size: 1.2rem;
+    cursor: pointer;
+    padding: 0.2rem 0.5rem;
+    border-radius: 4px;
+    color: #6c757d;
+}
+
+.close-btn:hover {
+    background: #f1f3f5;
+    color: #212529;
+}
+
+.thread-root-message {
+    padding: 0.8rem 1rem;
+    background: #f8f9fa;
+    border-bottom: 1px solid #dee2e6;
+}
+
+.thread-root-message .message-author {
+    font-weight: 700;
+    font-size: 0.85rem;
+}
+
+.thread-root-message .message-content {
+    font-size: 0.85rem;
+    color: #495057;
+    margin-top: 0.3rem;
+}
+
+.thread-messages {
+    flex: 1;
+    overflow-y: auto;
+    padding: 0.8rem;
+    display: flex;
+    flex-direction: column;
+    gap: 0.4rem;
+}
+
+/* Empty state */
+.no-channel-selected {
